import fs from "node:fs";
import { captureFromHook } from "../chatSessions/index.js";
import { guardStop, recordReplayLaunches } from "./replayStopGuard.js";
const HOSTS_THAT_KEEP_THE_TURN_OPEN = new Set([
    "claude-code",
    "codex",
    "cursor",
]);
export function readHookStdin() {
    try {
        const raw = fs.readFileSync(0, "utf-8").trim();
        if (!raw) {
            return null;
        }
        return JSON.parse(raw);
    }
    catch {
        return null;
    }
}
function recordLaunches(hookType, input, agent) {
    if (hookType !== "PreToolUse" || !HOSTS_THAT_KEEP_THE_TURN_OPEN.has(agent)) {
        return;
    }
    try {
        recordReplayLaunches(input.session_id, input.tool_input);
    }
    catch { }
}
async function guardTurnEnd(hookType, input, agent) {
    if (hookType !== "Stop" || !HOSTS_THAT_KEEP_THE_TURN_OPEN.has(agent)) {
        return;
    }
    const output = await guardStop(input.session_id, agent, process.argv[1]);
    if (output !== null) {
        process.stdout.write(JSON.stringify(output));
    }
}
export async function runCaptureHook(hookType, agent = "claude-code", preParsedInput, pluginVersion) {
    const input = preParsedInput ?? readHookStdin();
    if (!input?.session_id) {
        return;
    }
    recordLaunches(hookType, input, agent);
    await captureFromHook(hookType, input, agent, pluginVersion).catch(() => undefined);
    await guardTurnEnd(hookType, input, agent).catch(() => undefined);
}
